function getPhenotype(genotype, trait){
  if(trait==="Blending_incomplete"){
    if(genotype==="AA") return "dominant";
    if(genotype==="aa") return "recessive";
    return "intermediate";
  } else {
    if(genotype==="AA" || genotype==="Aa") return "dominant";
    return "recessive";
  }
}
function phenotypeToTint(ph){
  if(ph==="dominant") return 0.9;
  if(ph==="recessive") return 0.1;
  return 0.5;
}
function phenotypeToSprite(ph){
  if(ph==="dominant") return "dominant_plant";
  if(ph==="recessive") return "recessive_plant";
  return "intermediate_plant";
}
function allelesOf(g){
  if(g==="AA") return ["A","A"];
  if(g==="aa") return ["a","a"];
  return ["A","a"];
}
exports.init = (params, rng) => {
  const p1 = params.parentalGenotype1 || "AA";
  const p2 = params.parentalGenotype2 || "aa";
  const trait = params.traitType || "Mendelian_complete_dominance";
  const inherit = params.inheritanceEnabled !== undefined ? params.inheritanceEnabled : true;
  const acquired = params.parentalAcquiredTrait || 0;
  const agents = [];
  const mkParent = (genotype, idx) => {
    const x = idx===0 ? 0.25 : 0.75;
    const y = 0.5 + rng.range(-0.05,0.05);
    const phenotype = getPhenotype(genotype, trait);
    return {id:"p"+idx, x, y, genotype, phenotype, isParent:true, trained: acquired===1, tint: phenotypeToTint(phenotype), sprite: phenotypeToSprite(phenotype)};
  };
  agents.push(mkParent(p1,0));
  agents.push(mkParent(p2,1));
  return {
    agents,
    counts:{total:0, dominant:0, recessive:0, intermediate:0},
    transmission:{totalFromAa:0, countA:0},
    nextId:2,
    p1, p2, trait, inherit, acquired
  };
};
exports.step = (state, params, rng) => {
  const p1 = params.parentalGenotype1 !== undefined ? params.parentalGenotype1 : state.p1;
  const p2 = params.parentalGenotype2 !== undefined ? params.parentalGenotype2 : state.p2;
  const trait = params.traitType !== undefined ? params.traitType : state.trait;
  const inherit = params.inheritanceEnabled !== undefined ? params.inheritanceEnabled : state.inherit;
  const acquired = params.parentalAcquiredTrait !== undefined ? params.parentalAcquiredTrait : state.acquired;
  const batch = 8;
  let agents = state.agents.slice();
  let counts = {...state.counts};
  let transmission = {...state.transmission};
  let nextId = state.nextId;
  for(let i=0;i<batch;i++){
    let genotype, phenotype;
    let alleleFromP1=null, alleleFromP2=null;
    if(!inherit){
      const isDom = rng.chance(0.5);
      phenotype = isDom ? "dominant" : "recessive";
      if(phenotype==="dominant"){
        genotype = rng.chance(0.5) ? "AA" : "Aa";
      } else {
        genotype = "aa";
      }
      if(p1==="Aa"){
        alleleFromP1 = rng.chance(0.5) ? "A" : "a";
        transmission.totalFromAa+=1;
        if(alleleFromP1==="A") transmission.countA+=1;
      }
      if(p2==="Aa"){
        alleleFromP2 = rng.chance(0.5) ? "A" : "a";
        transmission.totalFromAa+=1;
        if(alleleFromP2==="A") transmission.countA+=1;
      }
    } else {
      const a1 = allelesOf(p1);
      const a2 = allelesOf(p2);
      alleleFromP1 = rng.pick(a1);
      alleleFromP2 = rng.pick(a2);
      if(p1==="Aa"){
        transmission.totalFromAa+=1;
        if(alleleFromP1==="A") transmission.countA+=1;
      }
      if(p2==="Aa"){
        transmission.totalFromAa+=1;
        if(alleleFromP2==="A") transmission.countA+=1;
      }
      if(alleleFromP1==="A" && alleleFromP2==="A") genotype="AA";
      else if(alleleFromP1==="a" && alleleFromP2==="a") genotype="aa";
      else genotype="Aa";
      phenotype = getPhenotype(genotype, trait);
    }
    counts.total+=1;
    if(phenotype==="dominant") counts.dominant+=1;
    else if(phenotype==="recessive") counts.recessive+=1;
    else counts.intermediate+=1;
    const x = rng.range(0.05,0.95);
    const y = rng.range(0.1,0.9);
    const tint = phenotypeToTint(phenotype);
    const sprite = phenotypeToSprite(phenotype);
    agents.push({id:"o"+nextId, x, y, genotype, phenotype, isParent:false, trained:false, tint, sprite});
    nextId++;
    if(agents.length>400){
      const parents = agents.slice(0,2);
      const rest = agents.slice(2);
      const kept = rest.slice(-398);
      agents = parents.concat(kept);
    }
  }
  return {agents, counts, transmission, nextId, p1, p2, trait, inherit, acquired};
};
exports.observe = (state, params) => {
  const total = state.counts.total;
  const dom = state.counts.dominant;
  const inter = state.counts.intermediate;
  const totalFromAa = state.transmission.totalFromAa;
  const countA = state.transmission.countA;
  const fraction_dominant_phenotype = total>0 ? dom/total : 0;
  const fraction_dominant_phenotype_in_offspring = total>0 ? dom/total : 0;
  const fraction_intermediate_phenotype = total>0 ? inter/total : 0;
  const transmission_rate_A_from_Aa_parent = totalFromAa>0 ? countA/totalFromAa : 0;
  const trained_parents = state.agents.filter(a=>a.isParent && a.trained).length;
  const dominant_count = dom;
  return {fraction_dominant_phenotype, transmission_rate_A_from_Aa_parent, fraction_intermediate_phenotype, fraction_dominant_phenotype_in_offspring, trained_parents, dominant_count};
};
exports.view = (state, params) => {
  const agents = state.agents.map(a=>{
    let bubble;
    if(a.isParent && a.trained) bubble="trained";
    return {id:a.id, x:a.x, y:a.y, tint:a.tint, sprite:a.sprite, bubble};
  });
  return {kind:"population", agents};
};
